"""Reconstitui o ícone distribuído em texto, sem dependências externas."""
from pathlib import Path
import base64
ICON_BASE64 = ''

def prepare():
    target=Path(__file__).resolve().parents[1]/'src'/'horizonte.ico'
    target.write_bytes(base64.b64decode(ICON_BASE64))
    return target

if __name__=='__main__':print(prepare())
